  '.mp-seek:hover input::-webkit-slider-thumb,.mp-seek input:focus-visible::-webkit-slider-thumb,.mp-seek input:active::-webkit-slider-thumb{width:12px;height:12px;margin-top:3px;opacity:1;transform:scale(1.05)}',
